function genPage(dir,name,fullName,parentName,icon,color,capsStr,respStr){
  const isSub=!!parentName;
  const caps=capsStr.split(',');
  const resps=respStr.split(',');
  const pRoute=parentName?parentRouteMap[Object.keys(parentRouteMap).find(k=>parentName.includes(k.replace(/-/g,' ')))||'']||'':'';
  const pIcon=parentName?parentIconMap[parentName]||'Briefcase':'Briefcase';
  const pColor=parentName?parentColorMap[parentName]||'#007AFF':'#007AFF';
  const level=isSub?'Sub-Agent':'VP / Executive';
  const dept=dir.includes('customer')?'Customer Experience':'Sales & Revenue';
  const parentSlug=parentName?Object.keys(parentRouteMap).find(k=>parentName.includes(k.replace(/-/g,' ')))||'':'';

  const imports=`import React from 'react';
import { View, Text, StyleSheet, ScrollView, TouchableOpacity } from 'react-native';
import { useTheme } from '@/providers/ThemeProvider';
import { useRouter } from 'expo-router';
import { Activity, ${icon}, Clock, Target, Zap, ArrowRight, Briefcase, Star, CircleCheckBig, TrendingUp, BarChart3 } from 'lucide-react-native';
import AgentFeatures from '@/components/ai-agent/AgentFeatures';
`;

  const statsArr=isSub?[
    `{label:'Status',value:'Active',icon:Activity,color:'#34C759'}`,
    `{label:'Level',value:'Sub-Agent',icon:Briefcase,color:'#${color.replace('#','')}'}`,
    `{label:'Efficiency',value:'20x',icon:Target,color:'#FF9500'}`,
    `{label:'Parent',value:'${parentSlug}',icon:${pIcon},color:'#007AFF'}`
  ]:[
    `{label:'Tasks',value:'1.4K',icon:CircleCheckBig,color:'#34C759'}`,
    `{label:'Uptime',value:'99.9%',icon:Activity,color:'#007AFF'}`,
    `{label:'Response',value:'0.3s',icon:Clock,color:'#FF9500'}`,
    `{label:'Accuracy',value:'98.2%',icon:Target,color:'${color}'}`
  ];

  const parentSection=isSub?`
      <View style={[styles.section, { backgroundColor: theme.colors.card || '#F2F2F7' }]}>
        <Text style={[styles.sectionTitle, { color: theme.colors.text }]}>Parent Agent</Text>
        <TouchableOpacity onPress={() => router.push('${pRoute}')} style={[styles.parentCard, { backgroundColor: theme.colors.background || '#F2F2F7' }]}>
          <${pIcon} size={24} color="${pColor}" />
          <View style={styles.parentInfo}>
            <Text style={[styles.parentName, { color: theme.colors.text }]}>{${JSON.stringify(parentName)}}</Text>
            <Text style={[styles.parentDesc, { color: theme.colors.textSecondary }]}>Main Agent</Text>
          </View>
          <ArrowRight size={20} color={theme.colors.textSecondary} />
        </TouchableOpacity>
      </View>`:'';

  return `${imports}
export default function ${name.replace(/-([a-z])/g,(_,c)=>c.toUpperCase())}Page() {
  const { theme } = useTheme();
  const router = useRouter();
  const stats = [${statsArr.join(',')}];
  const capabilities = ${JSON.stringify(caps)};
  const responsibilities = ${JSON.stringify(resps)};
  return (
    <ScrollView style={[styles.container, { backgroundColor: theme.colors.background }]}>
      <View style={[styles.hero, { borderBottomColor: theme.colors.border || '#E5E5EA' }]}>
        <View style={[styles.heroIconWrap, { backgroundColor: '${color}20' }]}><${icon} size={48} color="${color}" /></View>
        <Text style={[styles.heroTitle, { color: theme.colors.text }]}>{${JSON.stringify(fullName)}}</Text>
        <Text style={[styles.heroSubtitle, { color: theme.colors.textSecondary }]}>${dept}</Text>
        <View style={styles.badgesRow}>
          <View style={[styles.badge, { backgroundColor: '#34C75922' }]}><Activity size={12} color="#34C759" /><Text style={[styles.badgeText, { color: '#34C759' }]}>Active</Text></View>
          <View style={[styles.badge, { backgroundColor: '${color}22' }]}><Star size={12} color="${color}" /><Text style={[styles.badgeText, { color: '${color}' }]}>${level}</Text></View>
        </View>
      </View>
      <View style={styles.statsContainer}>{stats.map((stat,i)=>(<View key={i} style={[styles.statCard, { backgroundColor: theme.colors.card || '#F2F2F7' }]}><stat.icon size={22} color={stat.color} /><Text style={[styles.statValue, { color: theme.colors.text }]}>{stat.value}</Text><Text style={[styles.statLabel, { color: theme.colors.textSecondary }]}>{stat.label}</Text></View>))}</View>
      <View style={[styles.section, { backgroundColor: theme.colors.card || '#F2F2F7' }]}><Text style={[styles.sectionTitle, { color: theme.colors.text }]}>Overview</Text><Text style={[styles.description, { color: theme.colors.textSecondary }]}>${fullName} - ${isSub?`Sub-agent supporting ${parentName}. Part of the Kaytx AI Workforce hierarchy providing automated capabilities.`:`Leading departmental strategy, managing cross-functional initiatives, and driving performance optimization within the ${dept} division.`}</Text></View>
      <View style={[styles.section, { backgroundColor: theme.colors.card || '#F2F2F7' }]}><Text style={[styles.sectionTitle, { color: theme.colors.text }]}>Capabilities</Text><View style={styles.tagsContainer}>{capabilities.map((cap,i)=>(<View key={i} style={[styles.tag, { backgroundColor: '${color}18' }]}><Text style={[styles.tagText, { color: '${color}' }]}>{cap}</Text></View>))}</View></View>
      <View style={[styles.section, { backgroundColor: theme.colors.card || '#F2F2F7' }]}><Text style={[styles.sectionTitle, { color: theme.colors.text }]}>Key Responsibilities</Text>{responsibilities.map((item,i)=>(<View key={i} style={styles.responsibilityRow}><ArrowRight size={14} color="${color}" /><Text style={[styles.responsibilityText, { color: theme.colors.textSecondary }]}>{item}</Text></View>))}</View>
      <View style={[styles.section, { backgroundColor: theme.colors.card || '#F2F2F7' }]}><Text style={[styles.sectionTitle, { color: theme.colors.text }]}>A2A Endpoints</Text>{['/consult/${name}','/${name}/execute','/${name}/analyze'].map((ep,i)=>(<View key={i} style={styles.endpointRow}><Zap size={14} color="#8B5CF6" /><Text style={[styles.endpointText, { color: theme.colors.textSecondary }]}>{ep}</Text></View>))}</View>${parentSection}
      <AgentFeatures agentId="${name}" agentName="${fullName}" />
      <View style={{ height: 40 }} />
    </ScrollView>
  );
}

const styles = StyleSheet.create({container:{flex:1},hero:{alignItems:'center',paddingVertical:32,paddingHorizontal:20,borderBottomWidth:1},heroIconWrap:{width:88,height:88,borderRadius:44,justifyContent:'center',alignItems:'center',marginBottom:16},heroTitle:{fontSize:26,fontWeight:'bold'},heroSubtitle:{fontSize:15,marginTop:4,fontWeight:'500'},badgesRow:{flexDirection:'row',gap:10,marginTop:16},badge:{flexDirection:'row',alignItems:'center',paddingHorizontal:10,paddingVertical:5,borderRadius:20,gap:4},badgeText:{fontSize:12,fontWeight:'600'},statsContainer:{flexDirection:'row',flexWrap:'wrap',padding:16,gap:12},statCard:{flex:1,minWidth:'22%',alignItems:'center',padding:14,borderRadius:12},statValue:{fontSize:18,fontWeight:'bold',marginTop:8},statLabel:{fontSize:11,marginTop:4},section:{marginHorizontal:16,marginBottom:16,padding:20,borderRadius:16},sectionTitle:{fontSize:18,fontWeight:'700',marginBottom:14},description:{fontSize:14,lineHeight:22},tagsContainer:{flexDirection:'row',flexWrap:'wrap',gap:8},tag:{paddingHorizontal:12,paddingVertical:6,borderRadius:20},tagText:{fontSize:12,fontWeight:'600'},responsibilityRow:{flexDirection:'row',alignItems:'center',marginBottom:10,gap:8},responsibilityText:{fontSize:14,flex:1,lineHeight:20},endpointRow:{flexDirection:'row',alignItems:'center',marginBottom:8,gap:8},endpointText:{fontSize:13,fontFamily:'monospace'},parentCard:{flexDirection:'row',alignItems:'center',padding:16,borderRadius:12,gap:12},parentInfo:{flex:1},parentName:{fontSize:16,fontWeight:'600'},parentDesc:{fontSize:12,marginTop:2}});
`;
}

let created=0, skipped=0;
agents.forEach(([dir,name,fullName,parentName,icon,color,caps,resps])=>{
  const fullDir=p.join(B,dir);
  mk(fullDir);
  const filePath=p.join(fullDir,`${name}.tsx`);
  if(fs.existsSync(filePath)){skipped++;return;}
  fs.writeFileSync(filePath,genPage(dir,name,fullName,parentName,icon,color,caps,resps));
  created++;
});
console.log(`Created: ${created}, Skipped (exist): ${skipped}`);
